// 1-entry-per-key memo of the diffraction reduction (the same pattern is re-analysed while other inputs change)
const XMEMO = new Map();
function xrdMemo(text, o, opt) { const key = JSON.stringify(opt) + '|' + text.length + '|' + text.slice(0, 64) + text.slice(-64); if (isSynthetic(text)) o.synthetic = true; let A = XMEMO.get(key); if (!A || A.text !== text) { const t = parseTable(text, 2, 30, 'XRD pattern'); A = { text, A: xrdAnalyse(t.rows.map(r => r[0]), t.rows.map(r => r[1]), opt) }; if (XMEMO.size > 6) XMEMO.clear(); XMEMO.set(key, A); } return A.A; }

