  for (const l of String(inp.eds_table ?? '').split(/\r?\n/)) { const c = l.trim().split(/[,;\t]/).map(s => s.trim()); if (c.length >= 2 && chem.ELEMENTS[c[0]] && Number.isFinite(Number(c[1])) && c[1] !== '') { eds[c[0]] = [Math.max(0, Number(c[1])), Math.max(0.05, fin(Number(c[2]), inp.eds_dl))]; nE++; } }
