  o.E('governing', 'Inverse problem solved (periodicity)', 'f* = argmax_f |FFT{w(x)·(I(x) − trend)}|²;  p = 1/f*'); o.E('formula', 'Autocorrelation', 'C(Δ) = Σ I(x)·I(x + Δ)/Σ I²;  first side maximum at Δ = p'); o.E('formula', 'Symmetry test', 'square: p₂/p₁ = 1 (90°);  hexagonal: p₂/p₁ = √3/2 or 2/√3 (90°), 1 (60°)'); o.E('formula', 'Frequency resolution', 'u(f) ≈ 1/(L·√12)  ⇒  u(p)/p ≈ p/(L·√12)');
