    let z = csqrt(cdiv(csub(cmul(a, a), s2), csub(cmul(b, b), s2))); if (z[0] < 0) z = [-z[0], -z[1]];
    const X = cdiv(S21, csub([1, 0], cmul(S11, cdiv(csub(z, [1, 0]), cadd(z, [1, 0]))))), ni = -Math.log(Math.max(1e-300, cabs(X))) / kd, ph = Math.atan2(X[1], X[0]);
    let m = 0; if (prev !== null) m = Math.round((prev * kd - ph) / (2 * PI)); const nr = (ph + 2 * PI * m) / kd; prev = nr;
    const nn = [nr, ni]; nR.push(nn); zR.push(z); eR.push(cdiv(nn, z)); mR.push(cmul(nn, z)); if (ni >= -0.02) passN++; if (z[0] >= 0) passZ++; if (rows[i][1] ** 2 + rows[i][3] ** 2 <= 1.02) energy++;
