  const amin = N.minOf(models.map(m => m.aic)); o.hyp = rankHyp(models.map(m => ({ name: m.name, logL: -(m.aic - amin) / 2, basis: `ΔAIC = ${F(m.aic - amin, 3)}, RMS residual ${F(Math.sqrt(m.cost / (4 * n)) * ysc, 2)} on ε and µ; parameters ${m.p.map(v => F(v, 3)).join(', ')}`, m })));
