  o.K('f0', drude ? 'Plasma frequency of the fitted model' : 'Resonance frequency f₀', f0, 'GHz', `From the ${bm.name} fitted to the retrieved complex ε(f) and µ(f) by Levenberg–Marquardt; standard error ± ${F(fin(seF), 2)} GHz.`, Number.isFinite(seF) && seF / f0 < 0.02);
