  o.K('mu_min', 'Minimum Re µ in the band', muMin, '', negMu.length ? `Re µ < 0 from ${F(negMu[0], 4)} to ${F(negMu[negMu.length - 1], 4)} GHz (magnetic stop band). Passivity requires Im µ ≥ 0 for exp(−iωt), checked below.` : 'Re µ stays positive over the measured band: no negative-permeability region.');
  o.K('eps_min', 'Minimum Re ε in the band', epsMin, '', negEps.length ? `Re ε < 0 from ${F(negEps[0], 4)} to ${F(negEps[negEps.length - 1], 4)} GHz.` : 'Re ε stays positive over the measured band: no negative-permittivity region.');
  o.K('n_min', 'Minimum Re n in the band', nMin, '', `Branch-resolved refractive index (branch m = 0 at the lowest frequency, continuity afterwards); a negative value requires Re ε and Re µ to be simultaneously negative${nMin < 0 ? '' : ', which does not occur here'}.`);
  o.K('pass', 'Passivity satisfied', (passN + passZ) / (2 * n), 'fraction of points', `Fraction of frequency points with Im n ≥ 0 and Re z ≥ 0 after sign selection; ${energy} of ${n} points also satisfy |S11|² + |S21|² ≤ 1.`, passN === n && passZ === n);
  o.K('kd', 'Largest phase thickness |n|·k₀·d', kdMax, 'rad', 'Above about π the branch of the logarithm becomes ambiguous and the effective-medium description of a single slab breaks down.', kdMax < PI);
  o.K('n_geo', 'Split-ring geometries reproducing f₀', geos.length, '', `Different (radius, width, gap) sets with the same LC resonance from the compact estimate: the resonance frequency alone does not determine the geometry.`, geos.length >= 3);
  o.S('epsmu', 'Retrieved effective permittivity and permeability', 'frequency (GHz)', 'Re / Im', [['Re ε', f, eR.map(q => q[0])], ['Im ε', f, eR.map(q => q[1])], ['Re µ', f, mR.map(q => q[0])], ['Im µ', f, mR.map(q => q[1])]], 'Branch-resolved retrieval from the complex S-parameters of the slab; resonant dispersion in µ identifies a magnetic resonator.');
  o.S('fitm', 'Dispersion-model fit to the resonant quantity', 'frequency (GHz)', magnetic ? 'µ' : 'ε', [['retrieved Re', f, (magnetic ? mR : eR).map(q => q[0])], ['retrieved Im', f, (magnetic ? mR : eR).map(q => q[1])], ['model Re', f, f.map(x => bm.model(x, bm.p)[magnetic ? 1 : 0][0])], ['model Im', f, f.map(x => bm.model(x, bm.p)[magnetic ? 1 : 0][1])]], 'Performance reconstruction: the fitted resonator model re-simulated on the measured frequency grid.');
  o.S('nz', 'Refractive index and wave impedance', 'frequency (GHz)', 'Re / Im', [['Re n', f, nR.map(q => q[0])], ['Im n', f, nR.map(q => q[1])], ['Re z', f, zR.map(q => q[0])], ['Im z', f, zR.map(q => q[1])]], 'n and z are the directly retrieved quantities; ε = n/z and µ = n·z.');
