  o.ident = [['Resonance frequency f₀', Number.isFinite(seF) && seF / f0 < 0.02 ? 'identifiable' : 'weak', `± ${F(fin(seF), 2)} GHz`], ['Damping γ and strength F', bm.se && bm.se.every(Number.isFinite) ? 'identifiable' : 'weak', bm.se ? `relative errors ${bm.se.map((v, j) => F(100 * v / Math.abs(bm.p[j] || 1), 2) + ' %').join(', ')}` : 'covariance singular'], ['Magnetic vs electric origin of the resonance', o.hyp[0].score > 0.9 ? 'identifiable' : 'ambiguous', `evidence ${F(o.hyp[0].score, 3)} for the leading model`], ['Branch of Re n', kdMax < PI ? 'identifiable' : 'ambiguous', `|n|k₀d up to ${F(kdMax, 3)} rad`], ['Resonator geometry (r, w, g)', 'not identifiable', `${geos.length} geometries share the same L·C product; only f₀ = 1/(2π√(LC)) is measured`]];
