  o.E('governing', 'Inverse problem solved (parameter retrieval)', 'z = ±√{[(1 + S₁₁)² − S₂₁²]/[(1 − S₁₁)² − S₂₁²]};  exp(i·n·k₀·d) = S₂₁/[1 − S₁₁·(z − 1)/(z + 1)];  n = {arg(·) + 2πm − i·ln|·|}/(k₀d)'); o.E('constitutive', 'Effective parameters and passivity', 'ε = n/z,  µ = n·z;  Re z ≥ 0,  Im n ≥ 0  (exp(−iωt) convention)'); o.E('constitutive', 'Lorentz magnetic resonator', 'µ(f) = 1 − F·f²/(f² − f₀² + iγf)'); o.E('formula', 'Split-ring LC estimate', 'f₀ = 1/(2π√(LC));  L ≈ µ₀·r·[ln(8r/a) − 2], a = 0.2235(w + t);  C ≈ ε₀ε_eff·(w·t/g)·κ_w·κ_t (Palmer fringing factors)'); o.E('governing', 'Dispersion-model fit', 'min_p Σ_f |ε_ret − ε_model(f; p)|² + |µ_ret − µ_model(f; p)|²;  ranking by AIC');
  o.C('Passivity: Im n ≥ 0 at all frequencies', passN === n, `${passN}/${n} points`); o.C('Passivity: Re z ≥ 0 at all frequencies', passZ === n, `${passZ}/${n} points`); o.C('Energy conservation |S11|² + |S21|² ≤ 1', energy === n, `${energy}/${n} points`); o.C('Branch unambiguous (|n|k₀d < π)', kdMax < PI, `${F(kdMax, 3)} rad`);
  if (passN < n) o.W('Im n < 0 at some frequencies: measurement noise, a calibration-plane error or the wrong time convention (try the other phase convention).');
  o.W('Homogeneous-slab retrieval at normal incidence: bianisotropy, spatial dispersion and substrate asymmetry are neglected; near resonance the retrieved non-resonant parameter often shows an unphysical anti-resonance for real periodic structures.');
  o.W('The split-ring dimensions come from a compact LC estimate (order ±20–30 %); they are starting points for full-wave simulation, not a recovered geometry.');
  o.R('high', `Image the unit cell: ${geos.length} different rings give f₀ = ${F(f0, 4)} GHz, so the geometry is not recoverable from S-parameters alone.`, 'Only the product L·C is identified.');
  o.R('medium', kdMax >= PI ? 'Measure a thinner slab or lower frequencies so that |n|k₀d stays below π and the branch choice is unambiguous.' : `Verify the retrieved parameters with a second sample thickness; the present phase thickness (${F(kdMax, 2)} rad) keeps the branch unique.`, 'Branch ambiguity of the complex logarithm.');
