  o.numerics = { method: 'Branch-resolved S-parameter retrieval; Levenberg–Marquardt fits of Lorentz/Drude models (multi-start); bisection for the LC geometry', dof: 4 * n, iterations: N.sum(models.map(m => m.its)), residual: Math.sqrt(bm.cost / (4 * n)) * ysc };
