  o.K('n_sol', 'Recipes reproducing the measured length', sol.length, '', `Combinations on a ${Ts.length} × ${cs.length} grid of temperature and precursor concentration for which the growth model reaches ${F(Lm * 1e9, 4)} nm at some time; ${inW} of them fall inside the route's usual time window (${s.time_h[0]}–${s.time_h[1]} h).`, sol.length > 0);
