  o.W('The missing-strut relation is an empirical linear knock-down and the crack model is the dilute limit; both lose accuracy for large defect levels.');
  o.R('high', nObs ? `Leading explanation: ${top.name} (${top.unit} = ${F(top.mag, 3)}, evidence ${F(top.score, 3)}); confirm with "${o.exps[1][0]}" before changing the process.` : 'Measure the solid density and one conductivity: without them the five mechanisms cannot be ranked at all.', 'Evidence ranking over secondary observables.');
